package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicWholeRoundingTest {
 private Question q(String id,int a,int unit){return new Question(id,a+"을 "+unit+"의 자리까지 "+(id.equals("el_round_up")?"올림":id.equals("el_round_down")?"버림":"반올림")+"하면?","poison","999999999");}
 private long expected(int a,int unit,String id){long b=a/unit,r=a%unit;return (b+(id.equals("el_round_up")?(r>0?1:0):id.equals("el_round_down")?0:(r*2>=unit?1:0)))*unit;}
 @Test public void sevenUnitsAndFourModesUsePublicGivens(){Checker c=new Checker();int count=0;for(int unit:new int[]{10,100,1000,10000,100000,1000000,10000000})for(int a=0;a<1000;a++){
  for(String id:List.of("el_round","el_round_up","el_round_down")){Question q=q(id,a,unit);long e=expected(a,unit,id);assertTrue(c.check(q,List.of(),List.of(""+e)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(""+(e+1))).status);count++;}
  int b=999-a;Question q=new Question("el_estimate_ops",a+" + "+b+"의 각 수를 "+unit+"의 자리까지 어림하여 계산하면?","poison","999999999");long e=expected(a,unit,"el_round")+expected(b,unit,"el_round");assertTrue(c.check(q,List.of(),List.of(""+e)).correct());assertFalse(c.check(q,List.of(),List.of(""+(e+1))).correct());count++;
 }assertEquals(28000,count);}
 @Test public void largeHalfExactAndCarryBoundariesAndInputCompatibility(){Checker c=new Checker();for(int unit:new int[]{10,100,1000,10000,100000,1000000,10000000})for(int base:new int[]{0,unit,10000000-unit})for(int delta:new int[]{0,1,unit/2-1,unit/2,unit/2+1,unit-1}){int a=base+delta;if(a>10000000)continue;for(String id:List.of("el_round","el_round_up","el_round_down")){Question q=q(id,a,unit);long e=expected(a,unit,id);assertTrue(c.check(q,List.of(),List.of(e+".0")).correct());assertTrue(c.check(q,List.of(),List.of(e+"/1")).correct());}}Question q=q("el_round",9999999,10000000);assertTrue(c.check(q,List.of(),List.of("10000000")).correct());for(String raw:List.of("","abc","1/0","10+10","9".repeat(121)))assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(raw)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);q.prompt="invalid";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("999999999")).status);}
 @Test public void yearSixFreshSupplyAndBlankHelpVersionRemain(){Generator g=new Generator(new Random(189));var limits=GlobalCurriculum.limits("england-primary-2021-v1","el_round",6);List<String> recent=new ArrayList<>();Set<Integer> units=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next("el_round",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=RoundingRelations.read(q);assertTrue(Integer.parseInt(v.first())<=10000000);units.add(v.unit().intValueExact());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());assertEquals("rounding-relations-v1",q.studyGuide.teachingVersion);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertEquals(Set.of(10,100,1000,10000,100000,1000000,10000000),units);}
}
